func (t RealtimeMessage) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "account_changed":
		return t.AsRealtimeAccountChanged()
	case "announcements_changed":
		return t.AsRealtimeAnnouncementsChanged()
	case "chat_message":
		return t.AsRealtimeChatMessage()
	case "game_started":
		return t.AsRealtimeGameStarted()
	case "lobby":
		return t.AsRealtimeLobby()
	case "match_recorded":
		return t.AsRealtimeMatchRecorded()
	case "open_game_expired":
		return t.AsRealtimeOpenGameExpired()
	case "quick_match_queue":
		return t.AsRealtimeQuickMatchQueue()
	case "rematch":
		return t.AsRealtimeRematch()
	case "rematch_ended":
		return t.AsRealtimeRematchEnded()
	case "site_stats":
		return t.AsRealtimeSiteStats()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

